<?php
use Drupal\node\Entity\Node;
use Drupal\node\Entity\NodeType;
use Drupal\field\Entity\FieldConfig;
use Drupal\field\Entity\FieldStorageConfig;
use Drupal\Core\Entity\Entity\EntityViewDisplay;
use Drupal\paragraphs\Entity\Paragraph;
use Drupal\paragraphs\Entity\ParagraphsType;
use Drupal\search_api\Entity\Server;
use Drupal\search_api\Entity\Index;
use Drupal\search_api\Item\Field;

if (!str_starts_with((string) \Drupal::config('system.site')->get('name'), 'Evander Drupal')) throw new RuntimeException('Fixture site required.');
if (\Drupal::state()->get('evander_preview.components')) throw new RuntimeException('Already seeded');
$pt = ParagraphsType::create(['id' => 'preview_text', 'label' => 'Preview text']); $pt->save();
FieldStorageConfig::create(['field_name' => 'field_text', 'entity_type' => 'paragraph', 'type' => 'text_long'])->save();
FieldConfig::create(['field_name' => 'field_text', 'entity_type' => 'paragraph', 'bundle' => 'preview_text', 'label' => 'Text'])->save();
EntityViewDisplay::create(['targetEntityType' => 'paragraph', 'bundle' => 'preview_text', 'mode' => 'default', 'status' => TRUE])->setComponent('field_text', ['type' => 'text_default', 'label' => 'hidden'])->save();
FieldStorageConfig::create(['field_name' => 'field_sections', 'entity_type' => 'node', 'type' => 'entity_reference_revisions', 'settings' => ['target_type' => 'paragraph'], 'cardinality' => -1])->save();
FieldConfig::create(['field_name' => 'field_sections', 'entity_type' => 'node', 'bundle' => 'page', 'label' => 'Sections'])->save();
$display = EntityViewDisplay::load('node.page.default');
$display->setComponent('field_sections', ['type' => 'entity_reference_revisions_entity_view', 'label' => 'hidden', 'settings' => ['view_mode' => 'default']])->save();
$p = Paragraph::create(['type' => 'preview_text', 'status' => 1, 'field_text' => ['value' => '<h2>Paragraph section</h2><p>PARAGRAPH_PUBLIC_SENTINEL</p>', 'format' => 'full_html']]); $p->save();
$n = Node::create(['type' => 'page', 'title' => 'Paragraph fixture', 'status' => 1, 'field_sections' => [['target_id' => $p->id(), 'target_revision_id' => $p->getRevisionId()]]]); $n->save(); $ids['paragraph'] = $n->id();
$private = Paragraph::create(['type' => 'preview_text', 'status' => 0, 'field_text' => ['value' => 'PRIVATE_PARAGRAPH_SENTINEL', 'format' => 'full_html']]); $private->save();
$n = Node::create(['type' => 'page', 'title' => 'Unpublished paragraph fixture', 'status' => 1, 'field_sections' => [['target_id' => $private->id(), 'target_revision_id' => $private->getRevisionId()]]]); $n->save(); $ids['private_paragraph'] = $n->id();
$type = NodeType::create(['type' => 'layout_page', 'name' => 'Layout fixture']); $type->save(); node_add_body_field($type);
\Drupal::service('plugin.manager.block')->clearCachedDefinitions();
$display = EntityViewDisplay::load('node.layout_page.default'); $display->enableLayoutBuilder();
$section = new \Drupal\layout_builder\Section('layout_onecol');
$section->appendComponent(new \Drupal\layout_builder\SectionComponent(\Drupal::service('uuid')->generate(), 'content', ['id' => 'field_block:node:layout_page:body', 'label_display' => FALSE, 'provider' => 'layout_builder', 'context_mapping' => ['entity' => 'layout_builder.entity'], 'formatter' => ['type' => 'text_default', 'label' => 'hidden', 'settings' => [], 'third_party_settings' => []]]));
$display->removeAllSections()->appendSection($section)->save();
$n = Node::create(['type' => 'layout_page', 'title' => 'Layout page', 'status' => 1, 'body' => ['value' => '<h2>Layout section</h2><p>LAYOUT_PUBLIC_SENTINEL</p>', 'format' => 'full_html']]); $n->save(); $ids['layout'] = $n->id();
$block = \Drupal\block_content\Entity\BlockContent::create(['type' => 'basic', 'info' => 'Preview notice', 'status' => 1, 'body' => ['value' => '<h2>Notice</h2><p>BLOCK_PUBLIC_SENTINEL</p>', 'format' => 'full_html']]); $block->save();
\Drupal\block\Entity\Block::create(['id' => 'preview_notice', 'plugin' => 'block_content:' . $block->uuid(), 'theme' => \Drupal::config('system.theme')->get('default'), 'region' => 'content', 'settings' => ['label' => 'Preview notice', 'label_display' => FALSE], 'visibility' => ['request_path' => ['id' => 'request_path', 'pages' => '/node/' . $ids['layout'], 'negate' => FALSE]]])->save();
\Drupal::configFactory()->getEditable('evander_webmcp.settings')->set('allowed_fields', ['body', 'field_sections'])->set('allowed_blocks', ['preview_notice'])->save();
Server::create(['id' => 'preview', 'name' => 'Preview DB', 'status' => TRUE, 'backend' => 'search_api_db', 'backend_config' => ['database' => 'default:default', 'min_chars' => 2, 'matching' => 'words']])->save();
$index = Index::create(['id' => 'preview', 'name' => 'Public preview content', 'status' => TRUE, 'server' => 'preview', 'datasource_settings' => ['entity:node' => ['bundles' => ['default' => TRUE, 'selected' => []], 'languages' => ['default' => TRUE, 'selected' => []]]], 'processor_settings' => ['content_access' => ['weights' => ['preprocess_query' => -30]], 'entity_status' => ['weights' => ['preprocess_index' => -10]]], 'tracker_settings' => ['default' => []]]);
$index->addField((new Field($index, 'title'))->setLabel('Title')->setType('text')->setDatasourceId('entity:node')->setPropertyPath('title'));
$index->addField((new Field($index, 'body'))->setLabel('Body')->setType('text')->setDatasourceId('entity:node')->setPropertyPath('body:value'));
$index->save(); $index->indexItems();
\Drupal::state()->set('evander_preview.components', $ids);
echo json_encode($ids) . "\n";
